mapper.select:
SELECT * FROM TBL_FINANCING_MONITORING
WHERE DELETE_FLAG = 0

    AND ALERT_TYPE = #{alertType}


    AND ALERT_LEVEL = #{alertLevel}


    AND ALERT_STATUS = #{alertStatus}


    AND RELATED_FINANCING_ID = #{relatedFinancingId}


    AND COMPANY_ID = #{companyId}


    AND ALERT_DATE >= #{startDate}


    AND ALERT_DATE <= #{endDate}


    AND (ALERT_MESSAGE LIKE '%'||#{keyword}||'%'
         OR COMPANY_NAME LIKE '%'||#{keyword}||'%')

ORDER BY ALERT_DATE DESC
